#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-10

# strict-mode: opt-out this harness counts failures and prints a summary, so
# `-e` would abort on the first failing assertion and hide the rest.
# `set -uo pipefail` is set below.
#
# =============================================================================
# pre-push must run each discovered test with the right interpreter (#4024)
# =============================================================================
# bin/git-hooks/pre-push discovers unit tests with a glob that takes BOTH
# `test-*.sh` and `test-*.mjs`, then ran every one of them under `bash`. An ESM
# file under bash is a syntax error, so both .mjs unit tests were guaranteed
# failures the moment the runner executed.
#
# It never executed. The version-skip early exit at the top of the hook left
# the whole script for every conventional-commit branch, so the runner was
# dead code and the bug sat in it unseen. #4024 fixes both halves; this pins
# the dispatch half.
#
# Two assertions, and they check different things on purpose:
#
#   A. BEHAVIOURAL. Plant one .sh and one .mjs in a temp dir, each exiting 0
#      under its correct interpreter, and prove bash gets the .mjs wrong. This
#      is the premise the fix rests on, measured rather than asserted.
#   B. STRUCTURAL. The hook actually dispatches on extension. Without this, A
#      would keep passing after someone reverted the fix, because A does not
#      execute the hook.
#
# B alone would be a grep for a string. A alone would pass forever. Together
# they fail if either the rule or the reason stops holding.
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
HOOK="$REPO_ROOT/bin/git-hooks/pre-push"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }

echo "=========================================="
echo "  pre-push interpreter dispatch (#4024)"
echo "=========================================="

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork-dispatch.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

# ─── A. the premise, measured ───────────────────────────────────────
# Planted OUTSIDE tests/unit on purpose: a fixture named test-*.mjs inside
# tests/unit would be picked up by the hook's own glob and run for real.
printf '#!/usr/bin/env bash\nexit 0\n' > "$TMP/test-planted.sh"
printf '// planted ESM fixture\nimport { strict as assert } from "node:assert";\nassert.ok(true);\nprocess.exit(0);\n' \
  > "$TMP/test-planted.mjs"

bash "$TMP/test-planted.sh" >/dev/null 2>&1
if [[ $? -eq 0 ]]; then
  pass "a .sh fixture exits 0 under bash"
else
  fail "a .sh fixture should exit 0 under bash"
fi

node "$TMP/test-planted.mjs" >/dev/null 2>&1
if [[ $? -eq 0 ]]; then
  pass "a .mjs fixture exits 0 under node"
else
  fail "a .mjs fixture should exit 0 under node"
fi

# The whole reason the dispatch matters. If this ever stops being true, the
# fix is unnecessary and this test should be deleted rather than weakened.
bash "$TMP/test-planted.mjs" >/dev/null 2>&1
if [[ $? -ne 0 ]]; then
  pass "the same .mjs fixture FAILS under bash (the premise for dispatching)"
else
  fail "a .mjs fixture unexpectedly succeeded under bash — premise no longer holds"
fi

# ─── B. the hook actually dispatches ────────────────────────────────
if [[ ! -f "$HOOK" ]]; then
  fail "pre-push hook not found at $HOOK"
elif grep -qE '\*\.mjs\|\*\.js\)[[:space:]]*runner=node' "$HOOK"; then
  pass "pre-push selects node for .mjs/.js"
else
  fail "pre-push has no extension dispatch — .mjs tests would run under bash"
fi

# The runner must USE the variable, not merely set it. Setting `runner` and
# then still calling `bash "$test_file"` would pass the grep above while
# changing nothing, which is the failure mode a structural check invites.
if grep -qE '"\$runner"[[:space:]]+"\$test_file"' "$HOOK"; then
  pass "pre-push invokes the selected interpreter, not a hardcoded bash"
else
  fail "pre-push sets a runner but does not invoke it"
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
